{"rob": "robolang 1.3;

task photo_and_park(robot r, object vial, location fridge, location park, sensor cam) {
    pre { sensor_ok cam; }
    goal { robot_at r park; }
    plan {
        move r to fridge;
        inspect r vial using cam;
        move r to park;
    }
}
", "task": "photo_and_park", "bindings": [{"param": "r", "id": "rover1"}, {"param": "vial", "id": "vial2"}, {"param": "fridge", "id": "fridge"}, {"param": "park", "id": "scanner"}, {"param": "cam", "id": "cam_rover"}]}
